coding.solution:
def apdex(times, t, f):
    if not times:
        return None
    sat = sum(1 for x in times if x is not None and x <= t)
    tol = sum(1 for x in times if x is not None and t < x <= f)
    return round((sat + tol / 2) / len(times), 3)

