coding.solution:
def over_time(samples, granularity_ms):
    buckets = {}
    for ts, el in samples:
        b = ts // granularity_ms * granularity_ms
        buckets.setdefault(b, []).append(el)
    return [(b, round(sum(v) / len(v), 1)) for b, v in sorted(buckets.items())]
